        .clk(clk),
        .reset(reset),
        .in(in),
        .out(out)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to check output against expected value
    task check_output;
        input expected_out;
        begin
            @(posedge clk);
            #1; // Small delay to allow combinational/sequential update
            if (out !== expected_out) begin
                $display("Mismatch at time %0t: in=%b, expected_out=%b, got_out=%b", 
                         $time, in, expected_out, out);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        in = 0;

        // Apply synchronous reset
