        in = 0;
        check_output(1'b1); // Should transition to B, out=1

        // State B (out=1) --in=1--> State B (out=1)
        in = 1;
        check_output(1'b1); // Should stay in B, out=1

        // State B (out=1) --in=0--> State A (out=0)
        in = 0;
        check_output(1'b0); // Should transition to A, out=0

        // State A (out=0) --in=1--> State A (out=0)
        in = 1;
        check_output(1'b0); // Should stay in A, out=0

        // Test synchronous reset again
        @(negedge clk);
        reset = 1;
        in = 1; // Even with in=1, reset should force state B (out=1)

        @(posedge clk);
        #1;
        if (out !== 1'b1) begin
            $display("Synchronous reset check failed: expected out=1, got out=%b", out);
            errors = errors + 1;
        end

        // Release reset and finish test
        reset = 0;
        @(posedge clk);

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
